import { useEffect, useRef } from 'react';
import Lenis from 'lenis';

export default function useLenisSmoothScroll() {
  const lenisRef = useRef(null);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (prefersReduced) {
        return () => {};
      }
    }

    // Avoid native smooth interfering
    if (typeof document !== 'undefined') {
      document.documentElement.style.scrollBehavior = 'auto';
    }

    const lenis = new Lenis({
      duration: 1.05,
      easing: (t) => 1 - Math.pow(1 - t, 3), // smooth easeOutCubic
      smoothWheel: true,
      smoothTouch: true,
      touchMultiplier: 1.2,
      wheelMultiplier: 1,
      lerp: 0.1,
      syncTouch: true,
    });
    lenisRef.current = lenis;

    // Expose a global helper for components without direct access
    if (typeof window !== 'undefined') {
      window.__lenis = lenis;
      window.__smoothScrollTo = (target, options = {}) => {
        try {
          const el = typeof target === 'string' ? document.querySelector(target) : target;
          if (el) {
            lenis.scrollTo(el, { offset: -80, ...options });
          }
        } catch (e) {
          // no-op fallback
        }
      };
    }

    function raf(time) {
      lenis.raf(time);
      requestAnimationFrame(raf);
    }
    const id = requestAnimationFrame(raf);

    return () => {
      cancelAnimationFrame(id);
      lenis.destroy();
      lenisRef.current = null;
      if (typeof window !== 'undefined') {
        if (window.__lenis === lenis) window.__lenis = null;
        if (window.__smoothScrollTo) window.__smoothScrollTo = null;
      }
    };
  }, []);

  return lenisRef;
}
