import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MessageCircle, Github, Mail, FileText } from 'lucide-react';

const FloatingAction = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [showFab, setShowFab] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      // Show after scrolling past home section
      setShowFab(window.scrollY > window.innerHeight * 0.3);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const fabItems = [
    { 
      icon: Mail, 
      label: "Email", 
      href: "mailto:matthew.millward2012@gmail.com", 
      color: "glass-minimal hover:bg-neutral-700/20 hover:border-neutral-600/30 hover:text-neutral-200",
      description: "Send me an email"
    },
    { 
      icon: Github, 
      label: "GitHub", 
      href: "https://github.com/MMillward2012", 
      color: "glass-minimal hover:bg-neutral-700/30 hover:border-neutral-600/30 hover:text-white",
      description: "View my repositories"
    },
    { 
      icon: FileText, 
      label: "Resume", 
      href: "/CV.pdf", 
      download: true, 
      color: "glass-minimal hover:bg-neutral-600/20 hover:border-neutral-500/30 hover:text-neutral-200",
      description: "Download my CV"
    },
  ];

  return (
    <AnimatePresence>
      {showFab && (
        <motion.div
          className="fixed bottom-8 right-8 z-40"
          initial={{ scale: 0, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0, opacity: 0 }}
          transition={{ type: "spring", stiffness: 260, damping: 20 }}
        >
          {/* Action items */}
          <AnimatePresence>
            {isOpen && (
              <motion.div className="flex flex-col-reverse gap-3 mb-4">
                {fabItems.map((item, index) => {
                  const IconComponent = item.icon;
                  return (
                    <motion.a
                      key={index}
                      href={item.href}
                      download={item.download}
                      target={item.href.startsWith('http') ? '_blank' : undefined}
                      rel={item.href.startsWith('http') ? 'noopener noreferrer' : undefined}
                      className="premium-glass-card p-4 shadow-xl cursor-pointer group flex items-center gap-3 min-w-fit hover:premium-glass-card-hover transition-all duration-500 relative overflow-hidden"
                      initial={{ scale: 0, x: 20 }}
                      animate={{ scale: 1, x: 0 }}
                      exit={{ scale: 0, x: 20 }}
                      transition={{ 
                        type: "spring", 
                        stiffness: 260, 
                        damping: 20,
                        delay: index * 0.05 
                      }}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                    >
                      {/* Premium shine effect */}
                      <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/3 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-700" />
                      
                      <IconComponent className="w-5 h-5 flex-shrink-0 relative z-10 text-white" />
                      <span className="text-sm font-medium whitespace-nowrap relative z-10 text-white">
                        {item.label}
                      </span>
                    </motion.a>
                  );
                })}
              </motion.div>
            )}
          </AnimatePresence>

          {/* Main FAB button - Premium redesign */}
          <motion.button
            onClick={() => setIsOpen(!isOpen)}
            className="premium-glass-card p-5 shadow-2xl cursor-pointer flex items-center justify-center hover:premium-glass-card-hover transition-all duration-500 group relative overflow-hidden"
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.95 }}
            animate={{ rotate: isOpen ? 45 : 0 }}
            transition={{ type: "spring", stiffness: 260, damping: 20 }}
          >
            {/* Premium shine effect */}
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/5 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
            
            <MessageCircle className="w-7 h-7 text-white relative z-10" />
            
            {/* Enhanced mathematical symbols */}
            <motion.div
              className="absolute -top-2 -right-2 text-sm opacity-40 text-blue-400"
              animate={{ rotate: [0, 360] }}
              transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
            >
              ∮
            </motion.div>
            <motion.div
              className="absolute -bottom-2 -left-2 text-sm opacity-40 text-cyan-400"
              animate={{ rotate: [360, 0] }}
              transition={{ duration: 15, repeat: Infinity, ease: "linear" }}
            >
              ∇
            </motion.div>
          </motion.button>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default FloatingAction;
