import React from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';

export default function GlobalBackdrop() {
  const { scrollYProgress } = useScroll();
  const ySlow = useTransform(scrollYProgress, [0, 1], ['0%', '8%']);
  const yMid = useTransform(scrollYProgress, [0, 1], ['0%', '16%']);
  const yFast = useTransform(scrollYProgress, [0, 1], ['0%', '24%']);
  const opacityA = useTransform(scrollYProgress, [0, 1], [0.22, 0.12]);
  const opacityB = useTransform(scrollYProgress, [0, 1], [0.12, 0.22]);

  return (
    <motion.div
      className="fixed inset-0 -z-10 pointer-events-none"
      style={{ y: ySlow }}
      aria-hidden="true"
    >
  {/* Base gradient to avoid hard jumps between sections */}
  <div className="absolute inset-0 bg-gradient-to-b from-black via-[#0a0a0a] to-black" />

      {/* Luxury light orbs (very subtle) */}
      <motion.div
        className="absolute -top-20 left-1/3 w-[60vw] h-[60vw] rounded-full blur-[120px]"
        style={{
          background:
            'radial-gradient(circle at center, rgba(234,179,8,0.08), transparent 60%)',
          opacity: opacityA,
          y: yMid,
        }}
        animate={{ scale: [1, 1.05, 1] }}
        transition={{ duration: 20, repeat: Infinity }}
      />
      <motion.div
        className="absolute bottom-0 right-1/4 w-[50vw] h-[50vw] rounded-full blur-[120px]"
        style={{
          background:
            'radial-gradient(circle at center, rgba(202,138,4,0.08), transparent 60%)',
          opacity: opacityB,
          y: yFast,
        }}
        animate={{ scale: [1.05, 1, 1.05] }}
        transition={{ duration: 24, repeat: Infinity, delay: 4 }}
      />

      {/* Ultra-subtle grid to reinforce premium feel */}
      <div
        className="absolute inset-0 opacity-[0.02]"
        style={{
          backgroundImage:
            'radial-gradient(circle at 1px 1px, rgba(255,255,255,0.35) 1px, transparent 0)',
          backgroundSize: '44px 44px',
        }}
      />
    </motion.div>
  );
}
