import React, { useRef, useState, useEffect } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';
import { User, Code, Brain, Target } from 'lucide-react';

const AboutSection = () => {
	const sectionRef = useRef(null);
	const [isVisible, setIsVisible] = useState(false);
  
	const { scrollYProgress } = useScroll({
		target: sectionRef,
		offset: ["start end", "end start"]
	});

	const backgroundY = useTransform(scrollYProgress, [0, 1], ['0%', '30%']);
	const textY = useTransform(scrollYProgress, [0, 1], ['0%', '-10%']);

	useEffect(() => {
		const currentRef = sectionRef.current;
		const observer = new IntersectionObserver(
			([entry]) => {
				setIsVisible(entry.isIntersecting);
			},
			{ threshold: 0.1 }
		);

		if (currentRef) {
			observer.observe(currentRef);
		}

		return () => {
			if (currentRef) {
				observer.unobserve(currentRef);
			}
		};
	}, []);

	const values = [
		{
			icon: Brain,
			title: "Innovation",
			description: "Constantly pushing boundaries through mathematical modeling and computational thinking"
		},
		{
			icon: Code,
			title: "Technical Excellence",
			description: "Combining rigorous mathematical foundations with modern computational tools"
		},
		{
			icon: User,
			title: "Collaboration",
			description: "Working effectively across disciplines to solve complex, real-world challenges"
		},
		{
			icon: Target,
			title: "Impact",
			description: "Solving real-world problems through quantitative analysis and strategic thinking"
		}
	];

	return (
		<section 
			ref={sectionRef}
			id="about"
			className="relative min-h-screen section-seamless section-bridge py-20"
		>
			{/* Unified Background System */}
			<motion.div 
				className="absolute inset-0 pointer-events-none"
				style={{ y: backgroundY }}
			>
				{/* Seamless gradient overlay */}
				<div className="absolute inset-0 bg-gradient-to-br from-blue-500/3 via-transparent to-cyan-500/3"></div>
        
				{/* Premium floating orbs */}
				<motion.div 
					className="absolute top-1/3 right-1/4 w-[400px] h-[400px] bg-gradient-to-r from-blue-400/6 to-blue-600/6 rounded-full blur-3xl animate-float"
					animate={{ 
						scale: [1, 1.3, 1],
						opacity: [0.2, 0.4, 0.2],
						x: [0, -50, 0],
						y: [0, 30, 0]
					}}
					transition={{ duration: 22, repeat: Infinity, ease: "easeInOut" }}
				/>
        
				{/* Glass grid overlay */}
				<div className="absolute inset-0 opacity-10">
					<div className="absolute inset-0" style={{
						backgroundImage: `radial-gradient(circle at 1px 1px, rgba(59, 130, 246, 0.2) 1px, transparent 0)`,
						backgroundSize: '60px 60px'
					}} />
				</div>
			</motion.div>

			<div className="relative z-10 max-w-7xl mx-auto px-6">
				{/* Section Header */}
				<motion.div 
					className="text-center mb-20"
					style={{ y: textY }}
				>
					<motion.h2 
						className="heading-secondary text-white mb-6"
						initial={{ opacity: 0, y: 30 }}
						animate={isVisible ? { opacity: 1, y: 0 } : { opacity: 0, y: 30 }}
						transition={{ duration: 0.8, delay: 0.2 }}
					>
						About <span className="text-gradient-brand">Me</span>
					</motion.h2>
          
					<motion.p 
						className="text-xl text-gray-300 max-w-4xl mx-auto leading-relaxed"
						initial={{ opacity: 0, y: 20 }}
						animate={isVisible ? { opacity: 1, y: 0 } : { opacity: 0, y: 20 }}
						transition={{ duration: 0.8, delay: 0.4 }}
					>
						I'm a Mathematics student passionate about bridging theoretical concepts 
						with practical applications through computational thinking and innovative problem-solving.
					</motion.p>
				</motion.div>

				{/* Main Content Grid */}
				<div className="grid lg:grid-cols-2 gap-20 items-center">
          
					{/* Bio Content */}
					<motion.div
						initial={{ opacity: 0, x: -50 }}
						animate={isVisible ? { opacity: 1, x: 0 } : { opacity: 0, x: -50 }}
						transition={{ duration: 0.8, delay: 0.3 }}
					>
						<div className="premium-glass-card-ultra hover:premium-glass-card-ultra-hover transition-all duration-700 relative overflow-hidden">
							{/* Premium background effects */}
							<div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 via-transparent to-cyan-400/5 opacity-0 hover:opacity-100 transition-opacity duration-700" />
							<div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/2 to-transparent -translate-x-full hover:translate-x-full transition-transform duration-1000" />
							
							<div className="relative z-10 p-10">
								<h3 className="text-2xl font-bold text-white mb-6">My Journey</h3>
              
								<div className="space-y-6 text-gray-300 leading-relaxed text-lg font-light">
									<p>
									Currently pursuing my degree in Mathematics, I focus on the elegance of theory and its power
									to model complex, real-world phenomena with clarity and precision.
									</p>
                
									<p>
									I work across analysis, algebra, and statistical modeling, and build projects that connect
									mathematics to computation—spanning physics, finance, and data science.
									</p>
                
									<p>
									I believe in the transformative power of mathematics to address meaningful problems.
									My aim is to contribute through research, clear thinking, and collaborative execution.
									</p>
								</div>

								{/* Enhanced Skills Highlight */}
												<div className="mt-10 pt-8">
													<div className="hairline-divider mb-8" />
									<h4 className="text-xl font-semibold text-white mb-6">Core Expertise</h4>
									<div className="flex flex-wrap gap-3">
										{[
											"Mathematical Modeling", "Statistical Analysis", "Computational Mathematics",
											"Python/R", "Data Science", "Research Methods"
										].map((skill, index) => (
											<motion.span 
												key={skill}
												className="px-5 py-3 premium-glass-card text-sm text-blue-300 border border-blue-500/30 hover:premium-glass-card-hover transition-all duration-300 font-medium"
												whileHover={{ scale: 1.05, y: -2 }}
												initial={{ opacity: 0, y: 10 }}
												animate={{ opacity: 1, y: 0 }}
												transition={{ duration: 0.3, delay: index * 0.05 }}
											>
												{skill}
											</motion.span>
										))}
									</div>
								</div>
							</div>
						</div>
					</motion.div>

					{/* Values Grid */}
					<motion.div
						initial={{ opacity: 0, x: 50 }}
						animate={isVisible ? { opacity: 1, x: 0 } : { opacity: 0, x: 50 }}
						transition={{ duration: 0.8, delay: 0.5 }}
					>
						<div className="grid grid-cols-2 gap-6">
							{values.map((value, index) => (
								<motion.div
									key={value.title}
									className="premium-glass-card group hover:premium-glass-card-hover transition-all duration-700 relative overflow-hidden"
									initial={{ opacity: 0, y: 20 }}
									animate={isVisible ? { opacity: 1, y: 0 } : { opacity: 0, y: 20 }}
									transition={{ duration: 0.6, delay: 0.7 + index * 0.1 }}
									whileHover={{ scale: 1.03 }}
								>
									{/* Premium background effects */}
									<div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 via-transparent to-cyan-400/5 opacity-0 group-hover:opacity-100 transition-opacity duration-700" />
									<div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/2 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
									
									<div className="relative z-10 p-8">
										<motion.div 
											className="w-14 h-14 premium-glass-card rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-500 relative overflow-hidden"
											whileHover={{ rotate: 5 }}
										>
											<div className="absolute inset-0 bg-gradient-to-br from-blue-500/20 to-cyan-400/20 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
											<value.icon className="w-7 h-7 text-blue-400 relative z-10" />
										</motion.div>
					  
										<h4 className="text-xl font-semibold text-white mb-4 group-hover:text-blue-300 transition-colors duration-500">
											{value.title}
										</h4>
					  
										<p className="text-gray-400 text-base leading-relaxed font-light">
											{value.description}
										</p>
									</div>
								</motion.div>
							))}
						</div>
					</motion.div>
				</div>

				{/* Stats Section */}
				<motion.div 
					className="mt-20 pt-20 border-t border-white/10"
					initial={{ opacity: 0, y: 30 }}
					animate={isVisible ? { opacity: 1, y: 0 } : { opacity: 0, y: 30 }}
					transition={{ duration: 0.8, delay: 0.8 }}
				>
					<div className="grid md:grid-cols-3 gap-8 text-center">
						{[
							{ number: "3+", label: "Years of Study", description: "Advanced Mathematics" },
							{ number: "10+", label: "Projects Completed", description: "Computational & Research" },
							{ number: "100%", label: "Passion Driven", description: "Continuous Learning" }
						].map((stat, index) => (
							<motion.div
								key={stat.label}
								className="premium-glass-card hover:premium-glass-card-hover transition-all duration-700 relative overflow-hidden group"
								whileHover={{ scale: 1.05 }}
								initial={{ opacity: 0, y: 20 }}
								animate={isVisible ? { opacity: 1, y: 0 } : { opacity: 0, y: 20 }}
								transition={{ duration: 0.6, delay: 1 + index * 0.1 }}
							>
								{/* Premium background effects */}
								<div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 via-transparent to-cyan-400/5 opacity-0 group-hover:opacity-100 transition-opacity duration-700" />
								<div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/2 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
								
								<div className="relative z-10 p-8 text-center">
									<div className="text-5xl font-bold text-gradient-brand mb-3">{stat.number}</div>
									<div className="text-xl font-semibold text-white mb-2">{stat.label}</div>
									<div className="text-gray-400 font-light">{stat.description}</div>
								</div>
							</motion.div>
						))}
					</div>
				</motion.div>
			</div>
		</section>
	);
};

export default AboutSection;
