import React, { useState, useCallback } from 'react';
import './styles/App.css';
import Navbar from './scripts/Navbar_premium';
import GlobalBackdrop from './scripts/GlobalBackdrop';
import HomeSection from './scripts/HomeSection';
import AboutSection from './scripts/AboutSection';
import EducationSection from './scripts/EducationSection';
import ProjectsSection from './scripts/ProjectsSection_premium';
import ContactSection from './scripts/ContactSection_premium';
import FloatingAction from './scripts/FloatingAction';
import Footer from './scripts/Footer';
import ErrorBoundary from './scripts/ErrorBoundary';
import useLenisSmoothScroll from './scripts/useLenis';

const Portfolio = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const lenisRef = useLenisSmoothScroll();

  const scrollToSection = useCallback((sectionId) => {
    const section = document.getElementById(sectionId);
    if (section) {
      const lenis = lenisRef.current;
      if (lenis) {
        lenis.scrollTo(section, { offset: -80 });
      } else {
        section.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }
    setIsMenuOpen(false);
  }, [lenisRef]);

  return (
    <ErrorBoundary>
  <div className="min-h-screen text-white overflow-x-hidden bg-black">
  <GlobalBackdrop />
        <Navbar
          scrollToSection={scrollToSection}
          isMenuOpen={isMenuOpen}
          setIsMenuOpen={setIsMenuOpen}
        />
        <main className="relative bg-black">
          <HomeSection />
          <AboutSection />
          <EducationSection />
          <ProjectsSection />
          <ContactSection />
        </main>
        <FloatingAction />
  <Footer />
      </div>
    </ErrorBoundary>
  );
};

export default Portfolio;